let state={counts:{},history:[],name:'Dresseur',zone:'route',team:[],xp:{},reducedMotion:false},busy=false,view='',lastRoll=0;
try{const s=JSON.parse(localStorage.getItem(saveKey));if(s&&typeof s==='object'){if(s.counts&&typeof s.counts==='object')state.counts=Object.fromEntries(Object.entries(s.counts).filter(([id,n])=>pool.some(p=>p.id===+id)&&Number.isSafeInteger(n)&&n>0));if(Array.isArray(s.history))state.history=s.history.filter(id=>pool.some(p=>p.id===id)).slice(0,5);if(typeof s.name==='string')state.name=s.name.slice(0,24)||'Dresseur';if(zones.some(z=>z.id===s.zone))state.zone=s.zone;state.reducedMotion=!!s.reducedMotion;if(s.xp&&typeof s.xp==='object'&&!Array.isArray(s.xp))state.xp=Object.fromEntries(Object.entries(s.xp).filter(([id,n])=>state.counts[id]&&Number.isSafeInteger(n)&&n>0));if(Array.isArray(s.team))state.team=dedupeLines([...new Set(s.team.filter(id=>state.counts[id]&&pool.some(p=>p.id===id)))]).slice(0,6);else state.team=pool.filter(p=>state.counts[p.id]).sort((a,b)=>powers[b.id-1]-powers[a.id-1]).reduce((team,p)=>teamAfterCapture(team,p.id),[]);}}catch{}
