  if(token!==profileToken||view!=='profile')return;
  const st=computeStats(sp.stats,l.level),tp=types[id].map(t=>`<span class="type-badge" style="--tc:${typeColor(t)}">${TYPE_FR[t]||t}</span>`).join('');
  const stat=(n,v)=>`<div><span>${n}</span><b>${v}</b></div>`;
  const move=m=>`<li class="${isUsable(m)?'':'inactive'}" style="--tc:${typeColor(m.type)}"><b>${m.fr}</b><span class="type-badge">${TYPE_FR[m.type]||m.type}</span><small>${isUsable(m)?`Puissance ${m.power}`+(m.acc?` · Précision ${m.acc}`:''):'Effet à venir'}</small></li>`;
  const xpLine=l.capped?(l.evolvesAt?`Niveau max du stade (${l.cap})`:'Niveau maximum'):`${l.xp} / ${l.need} XP`;
