  const sc=(n,v,c)=>`<div class="pf-card"><div><span>${n}</span><b>${v}</b></div><div class="pf-bar"><i style="width:${Math.min(100,Math.round(v/(n==='PV'?(st.hp>60?st.hp:60):60)*100))}%;background:${c}"></i></div></div>`;
  const mvCard=(m,i)=>`<div class="pf-move${isUsable(m)?'':' off'}" style="--tc:${typeColor(m.type)}"><div><b>${m.fr}</b><span class="type-badge" style="--tc:${typeColor(m.type)}">${TYPE_FR[m.type]||m.type}</span></div><small>${isUsable(m)?`${m.cls==='physical'?'Physique':'Spécial'} · Puiss. <b>${m.power}</b> · Préc. <b>${m.acc??'—'}${m.acc?'%':''}</b>`:'Statut · <b>Effet à venir</b>'}</small></div>`;
