  const chip=(t,e)=>`<span class="type-badge" style="--tc:${typeColor(t)}">${TYPE_FR[t]} ${e===0?'immunisé':e>=1?'×'+e:e===.5?'½':'¼'}</span>`;
  const weak=Object.entries(mult).filter(([,e])=>e>1).sort((x,y)=>y[1]-x[1]).map(([t,e])=>chip(t,e)).join('')||'<small>Aucune</small>';
  const res=Object.entries(mult).filter(([,e])=>e<1).sort((x,y)=>x[1]-y[1]).map(([t,e])=>chip(t,e)).join('')||'<small>Aucune</small>';
  const next=Object.keys(evolvesFrom).map(Number).filter(n=>evolvesFrom[n]===id).map(n=>pool[n-1].name),prev=evolvesFrom[id]?pool[evolvesFrom[id]-1].name:null;
  const evo=[prev?`<span class="pf-evo">${prev}</span>`:'',`<span class="pf-evo here">${p.name}</span>`,...next.map(n=>`<span class="pf-evo soon">${n}${l.evolvesAt?' · niv. '+l.evolvesAt:''}</span>`)].filter(Boolean).join('<i>›</i>');
  const ribbon=Array.from({length:6},(_,i)=>{const m=state.team[i];return m?`<button class="pf-slot${m===id?' on':''}" data-profile="${m}" style="--tc:${typeColor(types[m][0])}" title="Profil de ${pool[m-1].name}" aria-label="Profil de ${pool[m-1].name}"${m===id?' aria-current="true"':''}><img src="${sprite(m)}" alt=""><strong>${pool[m-1].name}</strong><em>Niv. ${lv(m).level}</em></button>`:`<span class="pf-slot empty"><span>Libre</span></span>`;}).join('');
  const canAdd=!inTeam&&(state.team.length<6||state.team.some(m=>sameLine(m,id)));
